这段 Node.js 代码为什么会先打印 done，后面才打印任务结果？

```js
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));

async function run() {
  [1, 2, 3].forEach(async n => {
    await delay(10);
    console.log(n);
  });
  console.log('done');
}

run();
```

用 `for...of` 并在循环内等待：

```js
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));

async function run() {
  for (const n of [1, 2, 3]) {
    await delay(10);
    console.log(n);
  }
  console.log('done');
}

run();
```

预期依次输出 `1`、`2`、`3`、`done`。每次迭代都等待前一次完成，因此这是顺序执行，不是并发。

可以把处理函数注入进去，再断言调用顺序和返回值：

```js
const assert = require('node:assert/strict');

async function mapSequential(items, worker) {
  const results = [];
  for (const item of items) {
    results.push(await worker(item));
  }
  return results;
}

async function test() {
  const visited = [];
  const results = await mapSequential([1, 2, 3], async n => {
    await new Promise(resolve => setTimeout(resolve, 5));
    visited.push(n);
    return n * 2;
  });
  assert.deepEqual(visited, [1, 2, 3]);
  assert.deepEqual(results, [2, 4, 6]);
  console.log('sequential test passed');
}

test().catch(error => { console.error(error); process.exitCode = 1; });
```

使用 Node 运行时，预期只输出 `sequential test passed`。

可以让两个执行者共享一个递增索引，每个结果仍写回原位置：

```js
const assert = require('node:assert/strict');

async function mapWithLimit(items, limit, worker) {
  if (!Number.isInteger(limit) || limit < 1) throw new RangeError('limit must be a positive integer');
  const results = new Array(items.length);
  let nextIndex = 0;
  async function runner() {
    while (true) {
      const index = nextIndex++;
      if (index >= items.length) return;
      results[index] = await worker(items[index], index);
    }
  }
  const runnerCount = Math.min(limit, items.length);
  await Promise.all(Array.from({ length: runnerCount }, () => runner()));
  return results;
}

async function test() {
  let active = 0;
  let maxActive = 0;
  const delays = [30, 5, 20, 1];
  const results = await mapWithLimit(delays, 2, async (ms, index) => {
    active += 1;
    maxActive = Math.max(maxActive, active);
    await new Promise(resolve => setTimeout(resolve, ms));
    active -= 1;
    return `task-${index}`;
  });
  assert.equal(maxActive, 2);
  assert.deepEqual(results, ['task-0', 'task-1', 'task-2', 'task-3']);
  assert.deepEqual(await mapWithLimit([], 2, async value => value), []);
  await assert.rejects(() => mapWithLimit([1], 0, async value => value), /positive integer/);
  console.log('bounded parallel test passed');
}

test().catch(error => { console.error(error); process.exitCode = 1; });
```

预期只输出 `bounded parallel test passed`。测试同时验证最大并发数为 2、结果保持输入顺序、空输入和非法上限；并发限制若没有测量，便只是代码作者对自己的信任。
